package com.jack.jackmart.controller;
import com.jack.jackmart.listener.DatabaseInitializer;import com.jack.jackmart.dao.jdbc.CartDAOImpl;import com.jack.jackmart.service.CartService;import com.jack.jackmart.model.User;import javax.servlet.*;import javax.servlet.http.*;import java.io.IOException;
public class CartRemoveServlet extends HttpServlet {private CartService service;public void init(){service=new CartService(new CartDAOImpl(DatabaseInitializer.dataSource(getServletContext())));}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{User u=(User)r.getSession().getAttribute("user");service.remove(u.getId(),Long.parseLong(r.getParameter("productId")));s.sendRedirect(r.getContextPath()+"/cart");}catch(Exception e){throw new RuntimeException(e);}}}
